<template>
  <main class="page home-page">
    <header class="topbar home-topbar"><div class="brand-mark"><img class="brand-logo" :src="logo" alt="Venuo" /><div class="brand-copy"><strong>Venuo</strong><small>Explore Events</small></div></div><div class="home-actions"><button class="icon-button" title="搜索活动" @click="focusSearch"><AppIcon name="search" /></button><RouterLink v-if="auth.isLoggedIn" to="/reminders" class="icon-button" title="活动与出票提醒"><AppIcon name="bell" /></RouterLink><RouterLink v-if="!auth.isLoggedIn" class="login-link" to="/login">登录 / 注册</RouterLink><RouterLink v-else class="avatar" to="/profile" title="我的"><AppIcon name="user" size="18" /></RouterLink></div></header>
    <div class="container">
      <RouterLink v-if="auth.isGuest" class="guest-summary" to="/profile"><img :src="guestAvatar" alt="游客头像" /><span>{{ auth.guestName }} <small>游客</small></span><AppIcon name="chevron-right" size="16" /></RouterLink>
      <section v-if="couponFilterActive" class="coupon-context"><AppIcon name="ticket" size="20" /><div><b>{{route.query.couponName || '优惠券'}} · 适用活动</b><small>{{couponFilters.length ? couponFilters.map(c=>c.label).join('、') : '全部活动'}}，优惠资格以确认订单校验为准</small></div><button aria-label="清除优惠券活动筛选" @click="clearCouponFilter"><AppIcon name="close" size="16" /></button></section>
      <div class="search-box"><span><AppIcon name="search" size="21" /></span><input ref="searchInput" v-model="keyword" placeholder="搜索演唱会、话剧、运动..." @keyup.enter="load" /><button v-if="keyword" type="button" title="清除搜索" @click="keyword='';load()"><AppIcon name="close" size="16" /></button></div>
      <div v-if="recentSearches.length && !keyword" class="recent-searches"><span>最近搜索</span><button v-for="item in recentSearches" :key="item" @click="keyword=item;load()">{{ item }}</button><button class="clear-recent" @click="clearRecent">清除</button></div>
      <div class="chips"><button v-for="item in categories" :key="item" :class="{active: category === item}" @click="selectCategory(item)">{{ item }}</button></div>
      <div class="subfilters"><div class="city-picker"><button class="city-trigger" type="button" @click="cityPickerOpen = true"><AppIcon name="pin" size="14" /><span>{{ selectedCity === 'ALL' ? '全部城市' : selectedCity }}</span><AppIcon name="chevron-right" size="13" /></button><div v-if="cityPickerOpen" class="city-overlay" @click.self="cityPickerOpen=false"><div class="city-panel"><div class="city-panel-head"><div><small>活动城市</small><b>选择城市</b></div><button type="button" @click="cityPickerOpen=false"><AppIcon name="close" size="16" /></button></div><div class="city-search"><AppIcon name="search" size="16" /><input v-model="cityQuery" placeholder="搜索城市" /></div><div class="city-grid"><button v-if="cityQuery.trim() && !cityOptions.includes(cityQuery.trim())" type="button" class="city-search-result" @click="selectedCity=cityQuery.trim();cityPickerOpen=false">使用“{{ cityQuery.trim() }}”筛选</button><button v-for="city in visibleCityOptions" :key="city" type="button" :class="{active:selectedCity===city}" @click="selectedCity=city;cityPickerOpen=false">{{ city === 'ALL' ? '全部城市' : city }}</button></div><p v-if="!visibleCityOptions.length" class="city-empty">没有找到匹配城市</p></div></div></div><button class="active">热门推荐</button><button>特惠折扣</button><button>排序方式 <AppIcon name="more" size="15" /></button></div>
      <div class="section-heading"><h2>热门活动</h2><button class="text-button" type="button" @click="load">刷新 <AppIcon name="refresh" size="14" /></button></div>
      <p v-if="loading" class="loading">正在为你寻找活动...</p>
      <section v-else-if="error" class="state-card error"><b>活动暂时加载失败</b><p>{{ error }}</p><button class="secondary-button" @click="load">重新加载</button></section>
      <section v-else-if="!filteredActivities.length" class="state-card empty"><span class="empty-icon"><AppIcon name="search" size="28" /></span><b>暂无匹配活动</b><p>换个关键词或清除筛选，看看其他城市活动。</p><button class="secondary-button" @click="resetFilters">查看全部</button></section>
      <div v-else class="activity-grid"><ActivityCard v-for="item in filteredActivities" :key="item.id" :activity="item" /></div>
    </div>
  </main>
</template>
<script setup>
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {couponCategoryFilter} from '../../utils/couponWallet'
import { activityApi } from '../../api/activity'
import ActivityCard from '../../components/ActivityCard.vue'
import AppIcon from '../../components/AppIcon.vue'
import logo from '../../assets/venu-logo.svg'
import guestAvatar from '../../assets/guest-avatar.jpg'
import { useAuthStore } from '../../stores/auth'
const allCategories = ['全部', '电影', '演唱会', '演出', '脱口秀', '展览艺术', '音乐节', '戏曲艺术', '体育运动', '话剧歌剧']
const category = ref('全部'), keyword = ref(''), activities = ref([]), loading = ref(false), error = ref(''), searchInput = ref(null), selectedCity = ref(localStorage.getItem('city-selected') || 'ALL'), cityPickerOpen = ref(false), cityQuery = ref('')
const auth = useAuthStore(),route=useRoute(),router=useRouter()
const couponFilters=computed(()=>couponCategoryFilter(route.query.couponCategories))
const couponFilterActive=computed(()=>Boolean(route.query.couponName || route.query.couponCategories))
const categories=computed(()=>couponFilters.value.length ? ['全部',...couponFilters.value.map(c=>c.label)] : allCategories)
const recentSearches = ref(JSON.parse(localStorage.getItem('city-recent-searches') || '[]'))
const defaultCities = ['北京','上海','天津','重庆','广州','深圳','杭州','南京','武汉','成都','西安','苏州','郑州','长沙','青岛','沈阳','大连','厦门','福州','济南','合肥','昆明','哈尔滨','长春','南昌','贵阳','太原','石家庄','南宁','海口','乌鲁木齐','兰州','银川','西宁','呼和浩特','拉萨','宁波','无锡','佛山','东莞','温州','嘉兴','绍兴','金华','常州','徐州','扬州','镇江','泰州','盐城','南通','淮安','连云港','芜湖','蚌埠','洛阳','开封','宜昌','襄阳','株洲','湘潭','岳阳','桂林','珠海','惠州','汕头','中山','江门','烟台','威海','临沂','泉州','漳州','九江','赣州','绵阳','乐山','泸州','三亚','大理']
const cityOptions = computed(() => ['ALL', ...new Set(defaultCities)])
const visibleCityOptions = computed(() => cityOptions.value.filter(city => city === 'ALL' || city.includes(cityQuery.value.trim())))
function resolveActivityCity(item) { const raw = `${item.city || ''} ${item.venueCity || ''} ${item.cityName || ''} ${item.venueName || ''} ${item.venueAddress || ''} ${item.title || ''}`; const aliases = { '江南大剧院':'南京', '华韵戏曲之夜':'南京' }; for (const [keyword, city] of Object.entries(aliases)) if (raw.includes(keyword)) return city; return defaultCities.find(city => raw.includes(city)) || '' }
const filteredActivities = computed(() => activities.value.filter(item=>(!couponFilters.value.length || couponFilters.value.some(c=>c.code===item.category)) && (selectedCity.value==='ALL' || resolveActivityCity(item)===selectedCity.value)))
function focusSearch() { nextTick(() => searchInput.value?.focus()) }
function clearRecent() { recentSearches.value=[]; localStorage.removeItem('city-recent-searches') }
let activityRequest=0
async function load() {
 const request=++activityRequest;loading.value=true;error.value=''
 try {
  if(keyword.value.trim()){recentSearches.value=[keyword.value.trim(),...recentSearches.value.filter(v=>v!==keyword.value.trim())].slice(0,5);localStorage.setItem('city-recent-searches',JSON.stringify(recentSearches.value))}
  const result=await activityApi.list(keyword.value.trim(),category.value)
  if(request===activityRequest)activities.value=result || []
 }catch(e){if(request===activityRequest)error.value=e.message || '网络请求失败'}finally{if(request===activityRequest)loading.value=false}
}
onUnmounted(()=>{activityRequest++})
function selectCategory(item) { category.value=item; load() }
function selectCity() { localStorage.setItem('city-selected', selectedCity.value) }
function resetFilters() { keyword.value=''; category.value='全部'; selectedCity.value='ALL'; localStorage.setItem('city-selected', 'ALL'); load() }
watch(selectedCity, selectCity)
function clearCouponFilter(){router.replace({path:'/home',query:{}})}
watch(()=>route.query.couponCategories,()=>{category.value='全部';if(couponFilterActive.value)selectedCity.value='ALL';load()})
onMounted(()=>{if(couponFilterActive.value)selectedCity.value='ALL';load()})
</script>
