ht:40px;border:1px solid #e3eaf5;border-radius:11px;background:#f8faff;color:#53637c;font-size:12px;transition:.15s}.city-grid button:hover{border-color:#bcd0ff;background:#f1f5ff;color:var(--primary)}.city-grid button.active{border-color:var(--primary);background:var(--primary-soft);color:var(--primary);font-weight:700}.city-grid .city-search-result{grid-column:1/-1;color:var(--primary);background:var(--primary-soft);border-color:#b9ccff}.city-empty{padding:22px 0;text-align:center;color:var(--muted);font-size:13px}.subfilters button{display:flex;align-items:center;justify-content:center;gap:3px;white-space:nowrap}.subfilters button:first-child{justify-content:flex-start}.subfilters button:last-child{justify-content:flex-end}.text-button{display:inline-flex;align-items:center;gap:3px;white-space:nowrap}</style>



